begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(15);
select is(public.is_intake_open(), false, 'intake starts closed');
select ok(not has_function_privilege('anon', 'public.complete_submission_upload(uuid)', 'execute'), 'anon cannot finalize an upload');
select ok(not has_function_privilege('authenticated', 'public.reconcile_submission_qa(uuid,text,text)', 'execute'), 'clients cannot approve their own QA');
insert into contributors(id,auth_uid,handle) values ('20000000-0000-4000-8000-000000000011','30000000-0000-4000-8000-000000000011','mobile-owner');
insert into contribution_grants(id,contributor_id,terms_version,accepted_at,attribution_name) values ('40000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000011','test',now(),'mobile');
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"30000000-0000-4000-8000-000000000011","role":"authenticated"}';
select throws_ok($$insert into submissions(id,contributor_id,grant_id,geom_precise,captured_at) values ('50000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000011','40000000-0000-4000-8000-000000000011',extensions.st_setsrid(extensions.st_makepoint(-79,40),4326),now())$$,'42501',null,'backend rejects uploads while closed');
reset role;
update intake_settings set enabled=true;
set local role authenticated;
insert into submissions(id,contributor_id,grant_id,geom_precise,captured_at) values ('50000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000011','40000000-0000-4000-8000-000000000011',extensions.st_setsrid(extensions.st_makepoint(-79,40),4326),now());
select throws_ok($$select complete_submission_upload('50000000-0000-4000-8000-000000000011')$$,'P0001','Required photos have not finished uploading','cannot finish without required photos');
select throws_ok($$insert into photos(submission_id,shot_type,storage_path) values ('50000000-0000-4000-8000-000000000011','A','someone-else/photo.jpg')$$,'42501',null,'photo paths must belong to the owner and submission');
insert into photos(submission_id,shot_type,storage_path) values
('50000000-0000-4000-8000-000000000011','A','30000000-0000-4000-8000-000000000011/50000000-0000-4000-8000-000000000011/A/60000000-0000-4000-8000-000000000011.jpg'),
('50000000-0000-4000-8000-000000000011','B','30000000-0000-4000-8000-000000000011/50000000-0000-4000-8000-000000000011/B/60000000-0000-4000-8000-000000000012.jpg');
select throws_ok($$select complete_submission_upload('50000000-0000-4000-8000-000000000011')$$,'P0001','Required photos have not finished uploading','rows without storage objects do not complete an upload');
insert into storage.objects(bucket_id,name) select 'incoming-photos',storage_path from photos where submission_id='50000000-0000-4000-8000-000000000011';
select lives_ok($$select complete_submission_upload('50000000-0000-4000-8000-000000000011')$$,'both photos can finalize an upload');
select lives_ok($$select complete_submission_upload('50000000-0000-4000-8000-000000000011')$$,'upload finalization is idempotent');
select throws_ok($$insert into photos(submission_id,shot_type,storage_path) values ('50000000-0000-4000-8000-000000000011','C','30000000-0000-4000-8000-000000000011/50000000-0000-4000-8000-000000000011/C/60000000-0000-4000-8000-000000000013.jpg')$$,'42501',null,'no late photo can enter a finalized upload');
set local role service_role;
update qa_jobs set status='completed' where photo_id=(select id from photos where submission_id='50000000-0000-4000-8000-000000000011' and shot_type='A');
select is(reconcile_submission_qa('50000000-0000-4000-8000-000000000011','86262b287ffffff','88262b2a37fffff'),'pending','one good photo cannot approve the full submission');
update qa_jobs set status='dead_letter' where photo_id=(select id from photos where submission_id='50000000-0000-4000-8000-000000000011' and shot_type='B');
select is(reconcile_submission_qa('50000000-0000-4000-8000-000000000011','86262b287ffffff','88262b2a37fffff'),'qa_fail','a corrupt required photo fails the submission');
update qa_jobs set status='completed' where photo_id=(select id from photos where submission_id='50000000-0000-4000-8000-000000000011' and shot_type='B');
select is(reconcile_submission_qa('50000000-0000-4000-8000-000000000011','86262b287ffffff','88262b2a37fffff'),'pending','completed jobs without check evidence cannot pass');
insert into qa_events(submission_id,check_name,passed) select '50000000-0000-4000-8000-000000000011',c || '_' || s,true from unnest(array['sharpness','exposure','card_detection','gps_plausibility','duplicate']) c cross join unnest(array['A','B']) s;
select is(reconcile_submission_qa('50000000-0000-4000-8000-000000000011','86262b287ffffff','88262b2a37fffff'),'qa_pass','a complete checked photo set passes');
update qa_events set passed=false where submission_id='50000000-0000-4000-8000-000000000011' and check_name='duplicate_B';
select is(reconcile_submission_qa('50000000-0000-4000-8000-000000000011','86262b287ffffff','88262b2a37fffff'),'flagged','failed duplicate check goes to review');
select * from finish();
rollback;
